describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 2000, costCents: 1000 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 3)], 5000),
      ).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      // 200g → first bracket (up to 500g) → 300
      expect(
        calc.computeShippingCents([makeLine("a", 200, 1)], 5000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // exactly 500g → first bracket
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
      ).toBe(300);
    });

    it("moves to next bracket when just over boundary", () => {
      // 501g → second bracket (up to 1000g) → 600
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 5000),
      ).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      // exactly 2000g → third bracket → 1000
      expect(
        calc.computeShippingCents([makeLine("a", 2000, 1)], 5000),
      ).toBe(1000);
    });

    it("uses overflowCostCents when weight exceeds all brackets", () => {
      // 2001g → overflow → 1500
      expect(
        calc.computeShippingCents([makeLine("a", 2001, 1)], 5000),
      ).toBe(1500);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      // 1500g exceeds all brackets, no overflow → last bracket cost = 600
      expect(
        noOverflow.computeShippingCents([makeLine("a", 1500, 1)], 5000),
      ).toBe(600);
    });

    it("sorts brackets by upToGrams regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first sorted bracket (500g) → 300
      expect(
        unordered.computeShippingCents([makeLine("a", 400, 1)], 5000),
      ).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      // 300*2 + 200*1 = 800g → second bracket (up to 1000g) → 600
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });
  });
});

