describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 3 },
    ];
    // 200*2 + 500*3 = 400 + 1500 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 2)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 100.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for a non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(599);
    });

    it("returns flat fee when freeOverCents is undefined", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 99999)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 2000, costCents: 1000 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 3)], 5000),
      ).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      // 200g → first bracket (up to 500g) → 300
      expect(
        calc.computeShippingCents([makeLine("a", 200, 1)], 5000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // exactly 500g → first bracket
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
      ).toBe(300);
    });

    it("moves to next bracket when just over boundary", () => {
      // 501g → second bracket (up to 1000g) → 600
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 5000),
      ).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      // exactly 2000g → third bracket → 1000
      expect(
        calc.computeShippingCents([makeLine("a", 2000, 1)], 5000),
      ).toBe(1000);
    });

    it("uses overflowCostCents when weight exceeds all brackets", () => {
      // 2001g → overflow → 1500
      expect(
        calc.computeShippingCents([makeLine("a", 2001, 1)], 5000),
      ).toBe(1500);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      // 1500g exceeds all brackets, no overflow → last bracket cost = 600
      expect(
        noOverflow.computeShippingCents([makeLine("a", 1500, 1)], 5000),
      ).toBe(600);
    });

    it("sorts brackets by upToGrams regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first sorted bracket (500g) → 300
      expect(
        unordered.computeShippingCents([makeLine("a", 400, 1)], 5000),
      ).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      // 300*2 + 200*1 = 800g → second bracket (up to 1000g) → 600
      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const makeLines = (): CartLine[] => [
    { product: { id: "a", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "b", name: "Gadget", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("updates prices from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(makeLines(), fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves other product properties", async () => {
    const lines: CartLine[] = [
      {
        product: { id: "a", name: "Widget", unitPriceCents: 100, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.name).toBe("Widget");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      "fetch failed",
    );
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  it("adds a product and reports itemCount", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 5)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    // Mutate snapshot — should not affect cart
    (snap as any)[0].quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — totals pipeline", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal sums unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(150),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };

    const cart = new Cart({
      discountPolicy,
      taxCalculator,
      shippingCalculator,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 3); // subtotal = 3000

    const t = cart.totals();

    // Discount receives subtotal
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(3000);
    expect(t.discountCents).toBe(500);

    // Tax receives discounted subtotal (3000 - 500 = 2500)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(2500, "US-CA");
    expect(t.taxCents).toBe(150);

    // Shipping receives lines and discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      2500,
    );
    expect(t.shippingCents).toBe(300);

    // total = discountedSubtotal + tax + shipping = 2500 + 150 + 300
    expect(t.totalCents).toBe(2950);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount > subtotal
    const bigDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: bigDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults region to US", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart — checkout()", () => {
  it("returns totals and lines for a basic checkout (no collaborators)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    // Price was updated to 1500, quantity 2 → subtotal 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("passes inventory check when available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when not available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("low stock");
    }
  });

  it("throws InventoryError for partial-stock denial (available: true but availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 1000,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };

    const cart = new Cart({
      discountPolicy,
      shippingCalculator,
      region: "FR",
    });
    cart.add(product("a", 5000), 2); // subtotal = 10000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2), // 20%
    };

    const result = await cart.checkout({ asyncTaxProvider });

    // subtotal = 10000, discount = 1000, discounted = 9000
    // tax = 20% of 9000 = 1800, shipping = 500
    // total = 9000 + 1800 + 500 = 11300
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.taxCents).toBe(1800);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(11300);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200) // product a → 1200
        .mockResolvedValueOnce(600), // product b → 600
    };

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10%
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal = 1200*2 + 600*1 = 3000
    // discount = 0 (default NoDiscountPolicy)
    // tax = 10% of 3000 = 300
    // shipping = 0 (default FreeShippingCalculator)
    // total = 3000 + 300 = 3300
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.totals.taxCents).toBe(300);
    expect(result.totals.totalCents).toBe(3300);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("checks inventory for each line and throws on first denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 500), 3);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("InventoryError has correct shape when no reason is given", async () => {
    const cart = new Cart();
    cart.add(product("x", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      const invErr = err as InventoryError;
      expect(invErr).toBeInstanceOf(InventoryError);
      expect(invErr.message).toContain("x");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(0);
    }
