import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  it("adds a product and reports itemCount", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 5)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    // Mutate snapshot — should not affect cart
    (snap as any)[0].quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — totals pipeline", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal sums unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(150),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };

    const cart = new Cart({
      discountPolicy,
      taxCalculator,
      shippingCalculator,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 3); // subtotal = 3000

    const t = cart.totals();

    // Discount receives subtotal
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(3000);
    expect(t.discountCents).toBe(500);

    // Tax receives discounted subtotal (3000 - 500 = 2500)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(2500, "US-CA");
    expect(t.taxCents).toBe(150);

    // Shipping receives lines and discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      2500,
    );
    expect(t.shippingCents).toBe(300);

    // total = discountedSubtotal + tax + shipping = 2500 + 150 + 300
    expect(t.totalCents).toBe(2950);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount > subtotal
    const bigDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: bigDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults region to US", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart — checkout()", () => {
  it("returns totals and lines for a basic checkout (no collaborators)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    // Price was updated to 1500, quantity 2 → subtotal 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("passes inventory check when available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when not available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("low stock");
    }
  });

  it("throws InventoryError for partial-stock denial (available: true but availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 1000,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };

    const cart = new Cart({
      discountPolicy,
      shippingCalculator,
      region: "FR",
    });
    cart.add(product("a", 5000), 2); // subtotal = 10000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2), // 20%
    };

    const result = await cart.checkout({ asyncTaxProvider });

    // subtotal = 10000, discount = 1000, discounted = 9000
    // tax = 20% of 9000 = 1800, shipping = 500
    // total = 9000 + 1800 + 500 = 11300
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.taxCents).toBe(1800);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(11300);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({ region: "US-CA" });
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200) // product a → 1200
        .mockResolvedValueOnce(600), // product b → 600
    };

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10%
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal = 1200*2 + 600*1 = 3000
    // discount = 0 (default NoDiscountPolicy)
    // tax = 10% of 3000 = 300
    // shipping = 0 (default FreeShippingCalculator)
    // total = 3000 + 300 = 3300
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.totals.taxCents).toBe(300);
    expect(result.totals.totalCents).toBe(3300);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("checks inventory for each line and throws on first denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 500), 3);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("InventoryError has correct shape when no reason is given", async () => {
    const cart = new Cart();
    cart.add(product("x", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      const invErr = err as InventoryError;
      expect(invErr).toBeInstanceOf(InventoryError);
      expect(invErr.message).toContain("x");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(0);
    }
  });
});
"}

