+    });
+
+    it("selects the first bracket that covers the weight", () => {
+      // 200g → first bracket (up to 500g) → 300
+      expect(
+        calc.computeShippingCents([makeLine("a", 200, 1)], 5000),
+      ).toBe(300);
+    });
+
+    it("selects bracket at exact boundary", () => {
+      // exactly 500g → first bracket
+      expect(
+        calc.computeShippingCents([makeLine("a", 500, 1)], 5000),
+      ).toBe(300);
