+      expect(
+        calc.computeShippingCents([makeLine("a", 501, 1)], 5000),
+      ).toBe(600);
+    });
+
+    it("selects highest bracket at its boundary", () => {
+      // exactly 2000g → third bracket → 1000
+      expect(
+        calc.computeShippingCents([makeLine("a", 2000, 1)], 5000),
+      ).toBe(1000);
+    });
+
+    it("uses overflowCostCents when weight exceeds all brackets", () => {
+      // 2001g → overflow → 1500
+      expect(
+        calc.computeShippingCents([makeLine("a", 2001, 1)], 5000),
+      ).toBe(1500);
+    });
+
+    it("falls back to heaviest bracket cost when no overflow specified", () => {
+      const noOverflow = new WeightBasedShippingCalculator([
+        { upToGrams: 500, costCents: 300 },
+        { upToGrams: 1000, costCents: 600 },
+      ]);
+      // 1500g exceeds all brackets, no overflow → last bracket cost = 600
+      expect(
+        noOverflow.computeShippingCents([makeLine("a", 1500, 1)], 5000),
+      ).toBe(600);
+    });
+
+    it("sorts brackets by upToGrams regardless of input order", () => {
+      const unordered = new WeightBasedShippingCalculator([
+        { upToGrams: 1000, costCents: 600 },
+        { upToGrams: 500, costCents: 300 },
+      ]);
+      // 400g → first sorted bracket (500g) → 300
+      expect(
+        unordered.computeShippingCents([makeLine("a", 400, 1)], 5000),
+      ).toBe(300);
+    });
+
+    it("accumulates weight across multiple lines", () => {
+      // 300*2 + 200*1 = 800g → second bracket (up to 1000g) → 600
+      const lines = [makeLine("a", 300, 2), makeLine("b", 200, 1)];
+      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
+    });
+  });
+});
